import { ChangeDetectionStrategy, Component, input } from '@angular/core';
import { RouterLink } from '@angular/router';
import { CountryFlag } from './country-flag';
import type { Country } from './country.model';

/**
 * The app header, shared by the country chooser (no country) and the wizard shell (US-04-BR-20,
 * BR-21, ADR-0014 section 5): the product name and, for a resolved country, the country chip as a
 * link to the chooser. The chip's accessible name contains the visible country name (WCAG 2.5.3);
 * the flag is decorative.
 */
@Component({
  selector: 'app-site-header',
  imports: [RouterLink, CountryFlag],
  changeDetection: ChangeDetectionStrategy.OnPush,
  styleUrl: './site-header.css',
  templateUrl: './site-header.html',
})
export class SiteHeader {
  /** The country of the wizard page, or null on the chooser. */
  readonly country = input<Country | null>(null);
}
<header class="header">
  <div class="header__inner">
    <div class="header__brand">
      <svg class="mark" viewBox="0 0 32 32" aria-hidden="true" focusable="false">
        <defs>
          <linearGradient id="brand-mark-fill" x1="0" y1="0" x2="1" y2="1">
            <stop class="mark__from" offset="0" />
            <stop class="mark__to" offset="1" />
          </linearGradient>
        </defs>
        <rect width="32" height="32" rx="9" fill="url(#brand-mark-fill)" />
        <path class="mark__shield" d="M16 5.5 25 9v6.6c0 5-3.6 8.6-9 10.9-5.4-2.3-9-5.9-9-10.9V9z" />
        <path class="mark__check" d="m11.6 15.9 3 3 5.8-6.2" />
      </svg>
      <p class="header__product">Cotizador de seguro de auto</p>
    </div>
    @if (country(); as current) {
      <a class="chip" routerLink="/" [attr.aria-label]="'Cambiar país (actual: ' + current.name + ')'">
        <app-country-flag [code]="current.code" [accentRing]="true" />
        <span>{{ current.name }}</span>
      </a>
    }
  </div>
</header>
